         integer(ip), intent(in) :: unit  !! Fortran unit connected to DAS file.
         integer(ip), intent(in) :: recno  !! Number of record to read or write.
         integer(ip), intent(inout) :: record ( nwi )  !! DAS integer record.
      end subroutine dasioi

